    begin : P1_reg_process
      if (rst == 1'b1) begin
        P1_4 <= 32'h00000000;
      end
      else begin
        if (enb) begin
          P1_4 <= P1_3;
        end
      end
    end

  assign P1 = P1_4;

  assign P2_2 = 32'h00000000;

  always @(posedge clk)
    begin : rd_7_process
      if (rst == 1'b1) begin
        for(rd_7_t_1 = 32'sd0; rd_7_t_1 <= 32'sd2; rd_7_t_1 = rd_7_t_1 + 32'sd1) begin
          rd_7_reg[rd_7_t_1] <= 32'h00000000;
        end
      end
      else begin
        if (enb) begin
          for(rd_7_t_0_1 = 32'sd0; rd_7_t_0_1 <= 32'sd2; rd_7_t_0_1 = rd_7_t_0_1 + 32'sd1) begin
            rd_7_reg[rd_7_t_0_1] <= rd_7_reg_next[rd_7_t_0_1];
          end
        end
      end
    end

  always @* begin
    P2_3 = rd_7_reg[2];
    rd_7_reg_next[0] = P2_1;

    for(rd_7_t_0_0 = 32'sd0; rd_7_t_0_0 <= 32'sd1; rd_7_t_0_0 = rd_7_t_0_0 + 32'sd1) begin
      rd_7_reg_next[rd_7_t_0_0 + 32'sd1] = rd_7_reg[rd_7_t_0_0];
    end

  end

  assign P2_4 = (Out_1 == 1'b0 ? P2_2 :
              P2_3);

  always @(posedge clk)
    begin : P2_reg_process
      if (rst == 1'b1) begin
        P2_5 <= 32'h00000000;
      end
      else begin
        if (enb) begin
          P2_5 <= P2_4;
        end
      end
    end

  assign P2 = P2_5;

  assign active_rank_1 = 32'h3f800000;

  assign active_rank_2 = 32'h40000000;

  assign active_rank_3 = (Out_1 == 1'b0 ? active_rank_1 :
              active_rank_2);

  always @(posedge clk)
    begin : active_rank_reg_process
      if (rst == 1'b1) begin
        active_rank_4 <= 32'h00000000;
      end
      else begin
        if (enb) begin
          active_rank_4 <= active_rank_3;
        end
      end
    end

  assign active_rank = active_rank_4;

  assign ce_out = clk_enable;

endmodule  // water_filling_hw

